import { Component, h, Prop, State } from '@stencil/core';

export interface DataHeader {
  company: string;
  fullName: string;
}

// Component ui-dropdown: Deprecated
@Component({
  tag: 'ui-dropdown',
  styleUrl: 'ui-dropdown.css',
  shadow: true
})
export class UiDropDownComponent {
  @Prop() classes: string;
  @Prop() data: DataHeader = { company: '', fullName: '' };

  @State() isOpen: boolean;

  toggleCollapse(): void {
    this.isOpen = !this.isOpen;
  }

  render() {
    const dropdownClasses = ['relative bg-primary py-2 px-4 lg:py-2 lg:px-6 rounded-2xl flex flex-col w-full css-dropdown', this.classes].join(' ').trim().replace(/\s+/g, ' ');

    return (
      <div class={dropdownClasses}>
        <div class={`css-collapse css-dropdown js-collapse  ${this.isOpen ? 'is-open' : ''}`}>
          <div class="css-collapse-header flex items-center justify-between js-collapse-header" onClick={() => this.toggleCollapse()}>
            <div class="css-collapse-text">
              <p class="text-sm text-white leading-5 font-sans font-semibold hidden lg:block">{this.data.company || 'Multiplica Perú'}</p>
              <p class="text-white font-bold text-base lg:text-[18px] leading-6">{this.data.fullName || 'Talent Ready Perú SAC'}</p>
            </div>
            <i class="icon-chevron-down text-white cursor-pointer text-2xl font-bold"></i>
          </div>
          <div class="css-collapse-body js-collapse-body hidden w-full pt-4 bg-primary py-2 px-4 lg:pt-5 lg:pb-4 lg:px-3 absolute top-12 left-0 z-10 rounded-br-2xl rounded-bl-2xl">
            <div class="flex flex-col gap-4 w-full">
              <std-input type="search" placeholder="Buscar empresa"></std-input>
              <div class="flex flex-col gap-4 overflow-y-auto max-h-[272px] mb-16 p-1">
                <slot />
              </div>
            </div>
            <div class="absolute bottom-[-2px] left-0 w-full bg-alternative-light h-16 p-4 flex justify-center items-center rounded-br-2xl rounded-bl-2xl">
              <std-button label="Consultar" size="s" disabled classes="w-full"></std-button>
            </div>
          </div>
        </div>
      </div>
    );
  }
}
